def L(id, en, bg, cue="", refs=(), eq="", en_tts=None, bg_tts=None):
    d = {"id": id, "en": en, "bg": bg, "cue": cue, "refs": list(refs), "eq": eq}
    if en_tts: d["en_tts"] = en_tts
    if bg_tts: d["bg_tts"] = bg_tts
    return d

